click.script:
if (eventArgs && eventArgs[0]) { eventArgs[0].preventDefault(); eventArgs[0].stopPropagation(); }
const partner = item.name;
const prevLocal = localShortlist.value || [];
if (prevLocal.includes(partner)) {
  localShortlist.value = prevLocal.filter((n) => n !== partner);
  try { localStorage.setItem('connect_local_shortlist', JSON.stringify(localShortlist.value)); } catch (e) {}
  localShortlistDetails.update({ params: { names: JSON.stringify(localShortlist.value) } });
  localShortlistDetails.reload();
}
call('connect.api.customer.remove_from_shortlist', { partner }).then(() => { myShortlistFull.reload(); }).catch(() => {});

if (eventArgs && eventArgs[0]) { eventArgs[0].preventDefault(); eventArgs[0].stopPropagation(); }
if (!(myContext.data && myContext.data.customer) && !mockLoggedIn.value) {
  pendingAction.value = 'contact';
  pendingPartner.value = item.name;
  showLoginDialog.value = true;
  return;
}
call('connect.api.contact.start_partner_thread', { partner: item.name }).then((result) => {
  const query = { thread: result && result.thread };
  if (result && result.is_new_thread) query.requirement = '1';
  router.push('/messaging?' + new URLSearchParams(query).toString());
}).catch((err) => {
  toast({ title: 'Could not start conversation', text: (err && err.message) || 'Please try again', icon: 'x' });
});

try { localStorage.setItem('connect_mock_logged_in', '1'); } catch (e) {}
mockLoggedIn.value = true;
showLoginDialog.value = false;
(localShortlist.value || []).forEach((partner) => {
  call('connect.api.customer.add_to_shortlist', { partner }).catch(() => {});
});
myShortlistFull.reload();
const action = pendingAction.value;
const partner = pendingPartner.value;
pendingAction.value = '';
pendingPartner.value = '';
if (action === 'contact' && partner) {
  call('connect.api.contact.start_partner_thread', { partner }).then((result) => {
