resources.on_success:
function onSuccess(data) {
  if (bootstrapped.value) return;
  bootstrapped.value = true;
  try { mockLoggedIn.value = localStorage.getItem('connect_mock_logged_in') === '1'; } catch (e) {}
  try { localShortlist.value = JSON.parse(localStorage.getItem('connect_local_shortlist') || '[]'); } catch (e) { localShortlist.value = []; }
  localShortlistDetails.update({ params: { names: JSON.stringify(localShortlist.value) } });
  localShortlistDetails.reload();
}
